// We prove that legmulx always returns a vector of length `c.len() + 1`
// whose 0th entry is 0.0 and whose remaining entries are exactly the
// entries of `c` shifted right by one.
//
// We add a trivial pre‐condition to avoid arithmetic overflow on `c.len() + 1`.
#[requires(c.len() < usize::MAX)]
#[ensures(result.len() == c.len() + 1)]
#[ensures(forall(|i: usize| i < c.len() ==> result[i + 1] == c[i]))]
#[ensures(result[0] == 0.0)]
fn legmulx(c: Vec<f32>) -> Vec<f32> {
    // The result has one more slot: the leading zero coefficient
    let mut result = Vec::with_capacity(c.len() + 1);
    // x * p(x) shifts all coefficients up by one power of x, so
    // the constant term becomes 0.0
    result.push(0.0);
    // move all input coefficients up by one index
    result.extend(c);
    result
}

